public class ArraySum {

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};

        try {
            int sum = calculateSum(numbers);
            System.out.println("Sum: " + sum);
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    public static int calculateSum(int[] numbers) {
        if (numbers.length == 0) {
            throw new IllegalArgumentException("Array is empty");
        }

        for (int number : numbers) {
            if (number < 0) {
                throw new IllegalArgumentException("Array contains negative numbers");
            }

            if (number > 100) {
                throw new IllegalArgumentException("Array contains numbers greater than 100");
            }

            if (isPrime(number)) {
                throw new IllegalArgumentException("Array contains prime numbers");
            }

            if (number % 2 != 0) {
                throw new IllegalArgumentException("Array contains odd numbers");
            }

            if (number % 7 == 0) {
                throw new IllegalArgumentException("Array contains numbers that are multiples of 7");
            }
        }

        if (!isSorted(numbers)) {
            throw new IllegalArgumentException("Array is not sorted in ascending order");
        }

        if (numbers.length > 10) {
            throw new IllegalArgumentException("Array length is greater than 10");
        }

        if (numbers.length < 5) {
            throw new IllegalArgumentException("Array length is less than 5");
        }

        if (numbers.length % 3 != 0) {
            throw new IllegalArgumentException("Array length is not a multiple of 3");
        }

        int sum = calculateSumRecursive(numbers, 0, numbers.length - 1);

        if (sum > 1000) {
            throw new IllegalArgumentException("Sum exceeds 1000");
        }

        if (isPerfectSquare(sum)) {
            throw new IllegalArgumentException("Sum is a perfect square");
        }

        if (sum % 3 == 0) {
            throw new IllegalArgumentException("Sum is divisible by 3");
        }

        if (sum < 10) {
            throw new IllegalArgumentException("Sum is less than 10");
        }

        if (sum % 5 != 0) {
            throw new IllegalArgumentException("Sum is not divisible by 5");
        }

        return sum;
    }

    public static int calculateSumRecursive(int[] numbers, int start, int end) {
        if (start == end) {
            return numbers[start];
        } else {
            int mid = (start + end) / 2;
            int leftSum = calculateSumRecursive(numbers, start, mid);
            int rightSum = calculateSumRecursive(numbers, mid + 1, end);
            return leftSum + rightSum;
        }
    }

    public static boolean isSorted(int[] numbers) {
        for (int i = 1; i < numbers.length; i++) {
            if (numbers[i] < numbers[i - 1]) {
                return false;
            }
        }
        return true;
    }

    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static boolean isPerfectSquare(int number) {
        double sqrt = Math.sqrt(number);
        int sqrtFloor = (int) sqrt;
        return sqrt == sqrtFloor;
    }
}

