func fibonacciIterative(_ n: Int) -> [Int] {
    var sequence = [0, 1]
    var i = 1
    while sequence[i] <= n {
        let nextNumber = sequence[i] + sequence[i - 1]
        if nextNumber > n {
            break
        }
        sequence.append(nextNumber)
        i += 1
    }
    return sequence
}

func fibonacciRecursive(_ n: Int) -> [Int] {
    if n == 0 {
        return [0]
    } else if n == 1 {
        return [0, 1]
    } else {
        var sequence = fibonacciRecursive(n - 1)
        let nextNumber = sequence[sequence.count - 1] + sequence[sequence.count - 2]
        if nextNumber <= n {
            sequence.append(nextNumber)
        }
        return sequence
    }
}

