public class PrimeNumbers {
    public static void main(String[] args) {
        int n = getValidInput();
        int[] primeNumbers = new int[n];
        int sum = 0;

        int number = 2; // Starting from 2 as it is the first prime number

        // Loop until n prime numbers are found
        for (int i = 0; i < n; ) {
            if (isPrime(number)) {
                primeNumbers[i] = number;
                sum += number;
                i++;
            }
            number++;
        }

        // Print the prime numbers
        System.out.println("The first " + n + " prime numbers are:");
        for (int primeNumber : primeNumbers) {
            System.out.print(primeNumber + " ");
        }

        // Print the sum of prime numbers
        System.out.println("\nThe sum of the prime numbers is: " + sum);
    }

    // Method to check whether a number is prime or not
    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        // Check for divisibility by numbers from 2 to sqrt(number)
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }

    // Method to get valid input from the user
    public static int getValidInput() {
        Scanner scanner = new Scanner(System.in);
        int n;

        do {
            System.out.print("Enter a positive integer greater than 1 and less than or equal to 1000: ");
            n = scanner.nextInt();
        } while (n <= 1 || n > 1000);

        return n;
    }
}

