// Function to find all prime numbers up to a given number using the Sieve of Eratosthenes algorithm
function sieveOfEratosthenes(max) {
  let primes = [];
  let sieve = new Array(max + 1).fill(true);

  sieve[0] = false;
  sieve[1] = false;

  for (let i = 2; i * i <= max; i++) {
    if (sieve[i]) {
      for (let j = i * i; j <= max; j += i) {
        sieve[j] = false;
      }
    }
  }

  for (let i = 2; i <= max; i++) {
    if (sieve[i]) {
      primes.push(i);
    }
  }

  return primes;
}

// Function to filter the input array and return an array of prime numbers
function filterPrimes(arr) {
  let max = Math.max(...arr.map(Math.abs));
  let primes = sieveOfEratosthenes(max);
  let result = [];

  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];

    if (primes.includes(Math.abs(num)) && isPerfectSquare(num)) {
      result.push(num);
    }
  }

  return result;
}

