import java.util.Arrays;

public class Statistics {
    public static void main(String[] args) {
        int size = 100000000;
        float[] array = new float[size];

        // Fill the array with random floating-point values
        for (int i = 0; i < size; i++) {
            array[i] = (float) Math.random();
        }

        // Calculate and output the average
        float average = calculateAverage(array);
        System.out.println("Average: " + average);

        // Calculate and output the median
        float median = calculateMedian(array);
        System.out.println("Median: " + median);

        // Calculate and output the mode
        float mode = calculateMode(array);
        System.out.println("Mode: " + mode);

        // Calculate and output the standard deviation
        float standardDeviation = calculateStandardDeviation(array);
        System.out.println("Standard Deviation: " + standardDeviation);
    }

    public static float calculateAverage(float[] array) {
        float sum = 0;
        for (float value : array) {
            sum += value;
        }
        return sum / array.length;
    }

    public static float calculateMedian(float[] array) {
        Arrays.sort(array);
        int middleIndex = array.length / 2;
        if (array.length % 2 == 0) {
            return (array[middleIndex - 1] + array[middleIndex]) / 2;
        } else {
            return array[middleIndex];
        }
    }

    public static float calculateMode(float[] array) {
        float mode = array[0];
        int maxCount = 0;
        for (int i = 0; i < array.length; i++) {
            float value = array[i];
            int count = 0;
            for (int j = 0; j < array.length; j++) {
                if (array[j] == value) {
                    count++;
                }
            }
            if (count > maxCount) {
                maxCount = count;
                mode = value;
            }
        }
        return mode;
    }

    public static float calculateStandardDeviation(float[] array) {
        float average = calculateAverage(array);
        float sumOfSquares = 0;
        for (float value : array) {
            sumOfSquares += Math.pow(value - average, 2);
        }
        float variance = sumOfSquares / array.length;
        return (float) Math.sqrt(variance);
    }
}

