import ast

def calculate_median(numbers):
    # Handling an empty list
    if not numbers:
        raise ValueError("List is empty")

    # Converting non-numeric elements to numeric elements
    numbers = [float(num) for num in numbers if isinstance(num, (int, float)) or (isinstance(num, str) and num.isdigit())]

    # Sorting the list
    numbers.sort()

    # Calculating the median using a divide and conquer approach
    def find_median(nums):
        if len(nums) % 2 == 1:
            return nums[len(nums) // 2]
        else:
            return (nums[len(nums) // 2 - 1] + nums[len(nums) // 2]) / 2

    return find_median(numbers)

