def fibonacci(n):
    if n <= 0:
        return "n must be a positive integer greater than 2"
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    else:
        fib_sequence = [0, 1]
        for i in range(2, n):
            fib_sequence.append(fib_sequence[i-1] + fib_sequence[i-2])
        even_sum = sum([num for num in fib_sequence if num % 2 == 0])
        return fib_sequence, even_sum

