def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return b

def sum_of_prime_fibonacci_divisible_by_3(n):
    count = 0
    fib_sum = 0
    i = 1
    while count < n:
        fib = fibonacci(i)
        if fib % 3 == 0 and is_prime(fib):
            count += 1
            fib_sum += fib
        i += 1
    return fib_sum

