function isPrime(num) {
  // Check if num is divisible by any number less than its square root
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false; // num is divisible by i, so it's not a prime number
    }
  }

  return true; // num is not divisible by any number, so it's a prime number
}

