import math

def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if primes[i]:
            for j in range(i * i, n + 1, i):
                primes[j] = False
    return [num for num, is_prime in enumerate(primes) if is_prime]

def filter_primes(numbers):
    max_num = max(numbers)
    primes = sieve_of_eratosthenes(max_num)
    return [num for num in numbers if num in primes]

import datetime

class Transaction:
    def __init__(self, amount, timestamp):
        self.amount = amount
        self.timestamp = timestamp

class TransactionAnalyzer:
    def __init__(self):
        self.transactions = []
        self.hourly_average = {}

    def add_transaction(self, amount, timestamp):
        transaction = Transaction(amount, timestamp)
        self.transactions.append(transaction)

        # Update hourly average
        hour = timestamp.hour
        minute = timestamp.minute
        if hour not in self.hourly_average:
            self.hourly_average[hour] = [transaction.amount]
        else:
            self.hourly_average[hour].append(transaction.amount)

    def get_average_transaction_amount(self):
        now = datetime.datetime.now()
        sixty_days_ago = now - datetime.timedelta(days=60)

        relevant_transactions = [t for t in self.transactions if t.timestamp >= sixty_days_ago]

        if len(relevant_transactions) < 500:
            return None

        total_amount = sum(t.amount for t in relevant_transactions)
        return total_amount / len(relevant_transactions)

    def get_hourly_average_transaction_amount(self):
        hourly_average = []
        for hour in sorted(self.hourly_average.keys()):
            average = sum(self.hourly_average[hour]) / len(self.hourly_average[hour])
            hourly_average.append((hour, average))

        return hourly_average

