class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False
        self.frequency = 0


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True
        node.frequency += 1

    def delete(self, word):
        node = self.root
        if self.search(word):
            for char in word:
                node = node.children[char]
                node.frequency -= 1
            node.is_end_of_word = False

    def search(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def get_words_with_prefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return self._get_words_from_node(node, prefix)

    def _get_words_from_node(self, node, prefix):
        result = []
        if node.is_end_of_word:
            result.append(prefix)
        for char, child_node in node.children.items():
            result.extend(self._get_words_from_node(child_node, prefix + char))
        return result

    def get_k_most_frequent_words_with_prefix(self, prefix, k):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return self._get_k_most_frequent_words_from_node(node, prefix, k)

    def _get_k_most_frequent_words_from_node(self, node, prefix, k):
        result = []
        if node.is_end_of_word:
            result.append((prefix, node.frequency))
        for char, child_node in node.children.items():
            result.extend(self._get_k_most_frequent_words_from_node(child_node, prefix + char, k))
        result.sort(key=lambda x: x[1], reverse=True)
        return [word for word, _ in result[:k]]

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PairSum {
    public static void main(String[] args) {
        int[] array = {2, 3, 4, 5, 6, 7, 7, -3, -1, -5};
        int target = 9;

        List<int[]> pairs = findPairs(array, target);

        System.out.println("Pairs:");
        for (int[] pair : pairs) {
            System.out.println("(" + pair[0] + ", " + pair[1] + ")");
        }
    }

    public static List<int[]> findPairs(int[] array, int target) {
        List<int[]> pairs = new ArrayList<>();
        Map<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < array.length; i++) {
            int complement = target - array[i];
            if (map.containsKey(complement)) {
                pairs.add(new int[]{map.get(complement), i});
            }
            map.put(array[i], i);
        }

        return pairs;
    }
}

def check_divisibility(n):
    while n >= 6:
        n -= 6
    return n == 0 or n == 3

def print_prime_numbers(limit):
    primes = []
    for num in range(6, limit + 1, 6):
        if check_divisibility(num - 1):
            primes.append(num - 1)
        if check_divisibility(num + 1):
            primes.append(num + 1)
    print(primes)

