import time

def update_status(message, duration):
    if duration is None or not isinstance(duration, int) or duration <= 0:
        return "Error: Please provide a valid positive integer value for duration."
    if message is None or not isinstance(message, str) or len(message.split()) < 5:
        return "Error: Please provide a valid message with at least 5 words."
    if not os.getenv('SLACK_AUTH_TOKEN'):
        return "Error: User not authenticated with Slack."
    retry_count = 0
    while retry_count < 3:
        try:
            os.system('curl -X POST --data '{ "text": "' + message + '"}'' .....)
            with open('status_log.txt', 'a') as file:
                file.write(f"Status Update: {message}, Duration: {duration}\n")
            break
        except Exception as e:
            retry_count += 1
            print(f"Failed to post status update to Slack. Retrying in 5 seconds. Error: {str(e)}")
            time.sleep(5)
    else:
        return "Error: Failed to post status update to Slack after 3 attempts."

    average_duration = calculate_average_duration(duration)
    print(f"Average duration of successful status updates: {average_duration}")

def calculate_average_duration(duration):
    total_duration = 0
    update_count = 0
    with open('status_log.txt', 'r') as file:
        for line in file:
            if "Status Update" in line:
                update_count += 1
                total_duration += int(line.split(":")[1].split(",")[1].strip())
    return total_duration / update_count

